import"./modulepreload-polyfill-B5Qt9EMX.js";/* empty css              */document.addEventListener("DOMContentLoaded",()=>{const o=document.querySelectorAll("[data-tab]"),c=document.querySelectorAll("[data-panel]");o.forEach(e=>{e.addEventListener("click",()=>{o.forEach(s=>s.classList.remove("tab-active")),c.forEach(s=>s.classList.add("hidden")),e.classList.add("tab-active");const t=document.querySelector(`[data-panel="${e.dataset.tab}"]`);t&&t.classList.remove("hidden")})}),document.querySelectorAll(".faq-item").forEach(e=>{const t=e.querySelector(".faq-question");t&&t.addEventListener("click",()=>{e.classList.toggle("open")})});const a=document.querySelectorAll(".reveal");if("IntersectionObserver"in window){const e=new IntersectionObserver(t=>{t.forEach((s,i)=>{s.isIntersecting&&(setTimeout(()=>s.target.classList.add("visible"),i*60),e.unobserve(s.target))})},{threshold:.05,rootMargin:"0px 0px 0px 0px"});a.forEach(t=>{const s=t.getBoundingClientRect();s.top<window.innerHeight&&s.bottom>0?t.classList.add("visible"):e.observe(t)})}else a.forEach(e=>e.classList.add("visible"))});
